Stringhostname=argv[0];
StringmessageToSend=argv[1];
SocketconnectedSocket=newSocket(hostname,2718);
BufferedReaderfromServer=newBufferedReader
(newInputStreamReader(connectedSocket.getInputStream()));
PrintWritertoServer=newPrintWriter
(connectedSocket.getOutputStream(),true);
toServer.println(messageToSend);
StringretrievedMessage=fromServer.readLine();
System.out.println(retrievedMessage);
toServer.close();
fromServer.close();
connectedSocket.close();
}
